#include <cstdlib>
#include <filesystem>
#include <iostream>
#include "strut/codegen.h"
#include "strut/ir.h"
#include "strut/lexer.h"
#include "strut/parser.h"
#include "strut/sema.h"
#include "strut/source.h"
namespace { void req(bool x,const char*m){if(!x){std::cerr<<"FAIL: "<<m<<'\n';std::exit(1);}} }
int main(){strut::SourceFile s("hello.p","function add(int a, int b) -> int { return a + b; } function main() -> void { x := add(2,3); print(\"hello \" , x); return; }"); strut::Lexer l(s);auto lx=l.lex();strut::Parser p(lx.tokens);auto a=p.parse();req(a.ok(),"parse");strut::SemanticAnalyzer sem;auto sr=sem.analyze(a.program);req(sr.ok(),"sema");strut::IRLowerer lower;auto ir=lower.lower(a.program);ir.program.source_path="hello.p";strut::CppBackend b;auto g=b.generate(ir.program);req(g.cpp.find("strut_print")!=std::string::npos,"print generated");req(g.cpp.find("#line 1 \"hello.p\"")!=std::string::npos,"source line mapping generated");auto out=std::filesystem::temp_directory_path()/"strut_codegen_test";std::string err;req(b.compile(ir.program,out,err),err.c_str());req(std::filesystem::exists(out),"native executable");std::filesystem::remove(out);
{ strut::SourceFile ms("minimal.p","function main() -> void { int x := 1; print(x); return; }"); strut::Lexer ml(ms); auto mx=ml.lex(); strut::Parser mp(mx.tokens); auto ma=mp.parse(); req(ma.ok(),"minimal parse"); strut::SemanticAnalyzer msem; auto msr=msem.analyze(ma.program); req(msr.ok(),"minimal sema"); strut::IRLowerer mlower; auto mir=mlower.lower(ma.program); auto mg=b.generate(mir.program); req(mg.cpp.find("json.h")==std::string::npos,"minimal runtime omits JSONIC"); req(mg.cpp.size()<5000,"minimal runtime remains compact"); }
{ strut::SourceFile vs("vec.p","function main() -> void { int[] values := []; values.push(1); print(values.length); return; }"); strut::Lexer vl(vs); auto vx=vl.lex(); strut::Parser vp(vx.tokens); auto va=vp.parse(); req(va.ok(),"vector parse"); strut::SemanticAnalyzer vsem; auto vsr=vsem.analyze(va.program); req(vsr.ok(),"vector sema"); strut::IRLowerer vlower; auto vir=vlower.lower(va.program); auto vg=b.generate(vir.program); req(vg.cpp.find("#include <vector>")!=std::string::npos,"vector runtime includes vector"); req(vg.cpp.find("#include <array>")==std::string::npos,"dynamic vector omits array header"); req(vg.cpp.find("#include <optional>")==std::string::npos,"non-nullable vector omits optional header"); req(vg.cpp.find("#include <type_traits>")==std::string::npos,"simple vector omits type-traits header"); }
{ strut::SourceFile maps("map.p","function main() -> void { int[] values := [1,2]; doubled := values.map((int x) => x * 2); print(doubled.length); return; }"); strut::Lexer ml2(maps); auto mx2=ml2.lex(); strut::Parser mp2(mx2.tokens); auto ma2=mp2.parse(); req(ma2.ok(),"map parse"); strut::SemanticAnalyzer msem2; auto msr2=msem2.analyze(ma2.program); req(msr2.ok(),"map sema"); strut::IRLowerer mlower2; auto mir2=mlower2.lower(ma2.program); auto mg2=b.generate(mir2.program); req(mg2.cpp.find("#include <vector>")!=std::string::npos,"map runtime includes vector"); req(mg2.cpp.find("#include <type_traits>")!=std::string::npos,"map runtime includes type traits"); req(mg2.cpp.find("#include <optional>")==std::string::npos,"map without nullable/find omits optional header"); }
{ strut::SourceFile cs("containers.p","function main() -> void { vector<int> v := [1,2]; map<int,int> m := [1:2]; ordered_map<int,int> om; set<int> s := [1,2]; ordered_set<int> os; queue<int> q; stack<int> st; deque<int> dq; list<int> li; priority_queue<int> pq; priority_queue<int,min> minpq; s.add(3); print(s.contains(3)); m.insert(2,3); return; }"); strut::Lexer cl(cs); auto cx=cl.lex(); strut::Parser cp(cx.tokens); auto ca=cp.parse(); req(ca.ok(),"containers parse"); strut::SemanticAnalyzer csem; auto csr=csem.analyze(ca.program); req(csr.ok(),"containers sema"); strut::IRLowerer clower; auto cir=clower.lower(ca.program); auto cg=b.generate(cir.program); req(cg.cpp.find("#include <unordered_map>")!=std::string::npos,"hash map includes unordered_map"); req(cg.cpp.find("#include <map>")!=std::string::npos,"ordered map includes map"); req(cg.cpp.find("#include <unordered_set>")!=std::string::npos,"hash set includes unordered_set"); req(cg.cpp.find("#include <set>")!=std::string::npos,"ordered set includes set"); req(cg.cpp.find("#include <queue>")!=std::string::npos,"queue/priority queue includes queue"); req(cg.cpp.find("#include <stack>")!=std::string::npos,"stack includes stack"); req(cg.cpp.find("#include <deque>")!=std::string::npos,"deque includes deque"); req(cg.cpp.find("#include <list>")!=std::string::npos,"list includes list"); req(cg.cpp.find("json.h")==std::string::npos,"numeric collections keep minimal runtime"); auto co=std::filesystem::temp_directory_path()/"strut_collection_codegen_test"; std::string ce; cir.program.source_path="containers.p"; req(b.compile(cir.program,co,ce),ce.c_str()); std::filesystem::remove(co); }
{ strut::SourceFile ps("ptr.p","function read(int* p) -> int { return *p; } function replace(int* p) -> void { p = ptr(2); return; }"); strut::Lexer pl(ps); auto px=pl.lex(); strut::Parser pp(px.tokens); auto pa=pp.parse(); req(pa.ok(),"ptr parse"); strut::SemanticAnalyzer psem; auto psr=psem.analyze(pa.program); req(psr.ok(),"ptr sema"); strut::IRLowerer lower2; auto pir=lower2.lower(pa.program); auto pg=b.generate(pir.program); req(pg.cpp.find("read(const std::shared_ptr<std::int32_t>& p)")!=std::string::npos,"read-only ptr parameter borrowed"); req(pg.cpp.find("replace(std::shared_ptr<std::int32_t> p)")!=std::string::npos,"assigned ptr parameter remains owning value"); req(pg.cpp.find("#include <optional>")==std::string::npos,"non-nullable pointer runtime omits optional header"); }
return 0;}
